int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c;
    cin >> a >> b >> c;

    using Bits = bitset<501>;
    array<array<Bits, 6>, 501> first{}, second{};

    for (int start = 1; start <= 500; ++start) {
        for (int step = 0; step <= 50; ++step) {
            long long x1 = start + step * a;
            long long x2 = start + step * b;

            for (int offset = 0; offset <= 5; ++offset) {
                long long k1 = x1 - offset * c;
                long long k2 = x2 - offset * c;

                if (1 <= k1 && k1 <= 500)
                    first[start][offset].set(static_cast<size_t>(k1));

                if (1 <= k2 && k2 <= 500)
                    second[start][offset].set(static_cast<size_t>(k2));
            }
        }
    }

    for (int i = 1; i <= 500; ++i) {
        for (int j = 1; j <= 500; ++j) {
            Bits possible = first[i][0] | second[j][0];

            for (int offset = 1; offset <= 5 && possible.any(); ++offset)
                possible &= first[i][offset] | second[j][offset];

            if (possible.any()) {
                cout << "YES\n";
                return 0;
            }
        }
    }

    cout << "NO\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

bool canCover(const vector<ll>& values, ll b) {
    if (values.empty()) return true;

    ll mn = *min_element(values.begin(), values.end());
    ll mx = *max_element(values.begin(), values.end());

    if (b == 0) {
        return mn == mx && 1 <= mn && mn <= 500;
    }

    ll step = abs(b);
    for (ll value : values) {
        if ((value - mn) % step != 0) return false;
    }

    ll left, right;
    if (b > 0) {
        left = max(1LL, mx - 50 * step);
        right = min(500LL, mn);
    } else {
        left = max(1LL, mx);
        right = min(500LL, mn + 50 * step);
    }

    if (left > right) return false;

    ll delta = ((mn - left) % step + step) % step;
    return left + delta <= right;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, c;
    cin >> a >> b >> c;

    for (ll i = 1; i <= 500; ++i) {
        for (ll k = 1; k <= 500; ++k) {
            vector<ll> missing;

            for (ll l = 0; l <= 5; ++l) {
                ll value = k + l * c;
                bool covered = false;

                if (a == 0) {
                    covered = (value == i);
                } else {
                    ll difference = value - i;
                    if (difference % a == 0) {
                        ll position = difference / a;
                        covered = (0 <= position && position <= 50);
                    }
                }

                if (!covered) missing.push_back(value);
            }

            if (canCover(missing, b)) {
                cout << "YES\n";
                return 0;
            }
        }
    }

    cout << "NO\n";
    return 0;
}

