    static bitset<501> second[501][6];

    for (int start = 1; start <= 500; ++start) {
        for (int q = 0; q <= 50; ++q) {
            long long x = start + q * a;
            for (int l = 0; l <= 5; ++l) {
                long long k = x - l * c;
                if (1 <= k && k <= 500)
                    first[start][l].set(static_cast<size_t>(k));
            }
        }

        for (int q = 0; q <= 50; ++q) {
            long long x = start + q * b;
            for (int l = 0; l <= 5; ++l) {
                long long k = x - l * c;
                if (1 <= k && k <= 500)
                    second[start][l].set(static_cast<size_t>(k));
            }
        }
    }

    for (int i = 1; i <= 500; ++i) {
        for (int j = 1; j <= 500; ++j) {
            bitset<501> possible;
            possible.set();

            for (int l = 0; l <= 5; ++l)
                possible &= first[i][l] | second[j][l];

            possible.reset(0);
            if (possible.any()) {
                cout << "YES\n";
                return 0;
            }
        }
    }

    cout << "NO\n";
    return 0;
}

